package com.tanmay.vault;
import com.tanmay.vault.auth.AuthService;import com.tanmay.vault.cloud.SupabaseClient;import com.tanmay.vault.crypto.CryptoService;import com.tanmay.vault.model.Credential;import com.tanmay.vault.service.*;import okhttp3.OkHttpClient;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.awt.datatransfer.StringSelection;import java.nio.file.*;import java.util.*;import java.time.Instant;
public final class VaultApplication {
 private final CryptoService crypto=new CryptoService();private final OkHttpClient http=new OkHttpClient();private final String url=env("SUPABASE_URL"),anon=env("SUPABASE_ANON_KEY");private final Path dir=Path.of(System.getProperty("user.home"),".secure-vault");private CredentialService service;private byte[] key;private String token;
 public static void main(String[] a){SwingUtilities.invokeLater(()->new VaultApplication().authDialog());}private static String env(String k){return System.getenv().getOrDefault(k,"").replaceAll("/$","");}
 private void authDialog(){JTextField email=new JTextField(25);JPasswordField account=new JPasswordField(25),master=new JPasswordField(25);Object[] fields={"Supabase email",email,"Supabase account password",account,"Vault master password",master};Object[] choices={"Sign in","Create account"};int choice=JOptionPane.showOptionDialog(null,fields,"Secure Vault — Tanmay Jaiswal",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,choices,choices[0]);if(choice<0)return;try{if(url.isBlank()||anon.isBlank())throw new IllegalStateException("Configure SUPABASE_URL and SUPABASE_ANON_KEY in Windows environment variables.");Files.createDirectories(dir);AuthService auth=new AuthService(url,anon,http);AuthService.Session s=choice==0?auth.signIn(email.getText().trim(),new String(account.getPassword())):auth.signUp(email.getText().trim(),new String(account.getPassword()));if(s.userId().isBlank())throw new IllegalStateException("Supabase did not return a user ID.");token=s.accessToken();Path saltPath=dir.resolve("kdf-"+s.userId()+".salt");byte[] salt;if(Files.exists(saltPath)){salt=Files.readAllBytes(saltPath);if(salt.length!=16)throw new IllegalStateException("Local key salt is corrupt.");}else{salt=crypto.newSalt();Files.write(saltPath,salt,StandardOpenOption.CREATE_NEW);}key=crypto.deriveKey(master.getPassword(),salt);service=new CredentialService(crypto,new SupabaseClient(url,anon,http),token,key,dir.resolve("cache-"+s.userId()+".json"));Arrays.fill(master.getPassword(),'\0');Arrays.fill(account.getPassword(),'\0');vaultWindow();}catch(Exception e){error(e.getMessage());authDialog();}}
 private void vaultWindow(){JFrame f=new JFrame("Secure Vault");f.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);f.setSize(900,520);f.setLocationRelativeTo(null);DefaultTableModel model=new DefaultTableModel(new Object[]{"Website","Username","Password","Notes","ID"},0){public boolean isCellEditable(int r,int c){return false;}};JTable table=new JTable(model);table.removeColumn(table.getColumnModel().getColumn(4));JTextField query=new JTextField(14);JPanel top=new JPanel();top.add(new JLabel("Search"));top.add(query);JButton[] buttons={new JButton("Add"),new JButton("Edit"),new JButton("Delete"),new JButton("Show password"),new JButton("Copy password"),new JButton("Generate"),new JButton("Logout")};for(JButton b:buttons)top.add(b);f.add(top,BorderLayout.NORTH);f.add(new JScrollPane(table));Runnable refresh=()->{model.setRowCount(0);for(Credential c:service.search(query.getText()))model.addRow(new Object[]{c.website(),c.username(),"••••••••",c.notes(),c.id().toString()});};refresh.run();query.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){refresh.run();}public void removeUpdate(javax.swing.event.DocumentEvent e){refresh.run();}public void changedUpdate(javax.swing.event.DocumentEvent e){refresh.run();}});
 buttons[0].addActionListener(e->edit(null,refresh));buttons[1].addActionListener(e->{Credential c=selected(table);if(c!=null)edit(c,refresh);});buttons[2].addActionListener(e->{Credential c=selected(table);if(c!=null&&JOptionPane.showConfirmDialog(f,"Delete this credential?","Confirm",JOptionPane.YES_NO_OPTION)==0)try{service.delete(c.id());refresh.run();}catch(Exception x){error(x.getMessage());}});buttons[3].addActionListener(e->{Credential c=selected(table);if(c!=null)JOptionPane.showMessageDialog(f,c.password(),c.website(),JOptionPane.INFORMATION_MESSAGE);});buttons[4].addActionListener(e->{Credential c=selected(table);if(c!=null){Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(c.password()),null);new javax.swing.Timer(30000,x->{try{Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(""),null);}catch(Exception ignored){}((javax.swing.Timer)x.getSource()).stop();}).start();JOptionPane.showMessageDialog(f,"Copied; clipboard clear is attempted after 30 seconds.");}});buttons[5].addActionListener(e->{String p=new PasswordGenerator().generate(20);JTextField field=new JTextField(p);JOptionPane.showMessageDialog(f,field,"Generated password (copy manually)",JOptionPane.INFORMATION_MESSAGE);});buttons[6].addActionListener(e->{Arrays.fill(key,(byte)0);key=null;service=null;token=null;f.dispose();authDialog();});f.setVisible(true);}
 private Credential selected(JTable t){int r=t.getSelectedRow();if(r<0){error("Select a row first.");return null;}String id=(String)t.getModel().getValueAt(t.convertRowIndexToModel(r),4);return service.list().stream().filter(c->c.id().toString().equals(id)).findFirst().orElse(null);}
 private void edit(Credential old,Runnable refresh){JTextField w=new JTextField(old==null?"":old.website()),u=new JTextField(old==null?"":old.username()),p=new JTextField(old==null?"":old.password()),n=new JTextField(old==null?"":old.notes());Object[] a={"Website",w,"Username",u,"Password",p,"Optional notes",n};if(JOptionPane.showConfirmDialog(null,a,old==null?"Add credential":"Edit credential",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{service.save(new Credential(old==null?UUID.randomUUID():old.id(),w.getText(),u.getText(),p.getText(),n.getText(),Instant.now()));refresh.run();}catch(Exception e){error(e.getMessage());}}
 private void error(String s){JOptionPane.showMessageDialog(null,s==null?"Unexpected error":s,"Secure Vault",JOptionPane.ERROR_MESSAGE);}
}

